  "content": "# -*- coding: utf-8 -*-
"""
Workspace 文件内容解码脚本
对历史项目中的乱码文件进行多种编码尝试解码
"""
import os
import sys
import base64
import urllib.parse
import codecs

BASE = r"C:\Users\operator\AgentRuns\deployments\case_928ffa76892c\dep_20260803_161027_cf86cf36\Workspace"

def read_raw_bytes(filepath):
    with open(filepath, 'rb') as f:
        return f.read()

def read_as_text(filepath):
    """尝试多种编码读取文本"""
    raw = read_raw_bytes(filepath)
    encodings = ['utf-8', 'gbk', 'gb2312', 'gb18030', 'big5', 'latin-1', 'shift_jis', 'utf-16']
    for enc in encodings:
        try:
            text = raw.decode(enc)
            return f"[成功解码: {enc}]\n{text}"
        except:
            pass
    return f"[所有编码尝试失败] 原始字节: {raw[:200]}"

def try_url_decode(text):
    """尝试 URL 百分号解码"""
    try:
        decoded = urllib.parse.unquote(text, encoding='utf-8')
        if decoded != text:
            return decoded
    except:
        pass
    return None

def try_base64_decode(text):
    """尝试 Base64 解码"""
    text_stripped = text.strip()
    try:
        # 补齐 padding
        padding = 4 - len(text_stripped) % 4
        if padding != 4:
            text_stripped += '=' * padding
        decoded_bytes = base64.b64decode(text_stripped)
        # 尝试多种编码
        for enc in ['utf-8', 'gbk', 'gb18030', 'utf-16']:
            try:
                decoded = decoded_bytes.decode(enc)
                if any('\u4e00' <= c <= '\u9fff' for c in decoded):
                    return decoded
            except:
                pass
    except:
        pass
    return None

def analyze_file(filepath):
    """分析单个文件，返回所有可能的解码结果"""
    print(f"\n{'='*80}")
    print(f"文件: {filepath}")
    print(f"{'='*80}")

    raw = read_raw_bytes(filepath)
    print(f"文件大小: {len(raw)} 字节")
    print(f"前50字节(hex): {raw[:50].hex()}")

    # 先尝试直接作为文本读取
    text_result = read_as_text(filepath)
    print(f"\n--- 直接文本读取 ---")
    print(text_result[:500])

    # 如果直接读取的是ASCII文本，尝试URL解码和Base64解码
    try:
        raw_text = raw.decode('ascii', errors='ignore').strip()
        if raw_text:
            # URL解码
            url_decoded = try_url_decode(raw_text)
            if url_decoded:
                print(f"\n--- URL百分号解码结果 ---")
                print(url_decoded[:500])

            # Base64解码
            b64_decoded = try_base64_decode(raw_text)
            if b64_decoded:
                print(f"\n--- Base64解码结果 ---")
                print(b64_decoded[:500])

                # 对Base64解码后的结果再尝试URL解码
                url_after_b64 = try_url_decode(b64_decoded)
                if url_after_b64 and url_after_b64 != b64_decoded:
                    print(f"\n--- Base64+URL双重解码结果 ---")
                    print(url_after_b64[:500])
    except:
        pass

def main():
    # 扫描所有文件
    for root, dirs, files in os.walk(BASE):
        for fname in files:
            if fname == 'nul':
                continue
            fpath = os.path.join(root, fname)
            analyze_file(fpath)

if __name__ == '__main__':
    main()
